/* 2026-10-28_D-HIST-01_load_2022.sql
   D-HIST-01: traveler archive, 2022 folder - 548 machine runs (28 with no quantity recorded, loaded as excluded).
   Run after 2026-10-28_D-HIST-01_historical_runs.sql. Safe to re-run: rows are keyed on source_file and
   updated in place; a review_status set by hand (with a review_note) is kept. TEST first, then PROD. */

on conflict (source_file, source_seq) do update set
  extract_batch = excluded.extract_batch,
  folder_year = excluded.folder_year,
  folder_month = excluded.folder_month,
  folder_order = excluded.folder_order,
  folder_part = excluded.folder_part,
  order_number = excluded.order_number,
  part_number_raw = excluded.part_number_raw,
  customer_raw = excluded.customer_raw,
  customer_name = excluded.customer_name,
  order_qty = excluded.order_qty,
  order_kind = excluded.order_kind,
  machine_raw = excluded.machine_raw,
  machine_on_traveler = excluded.machine_on_traveler,
  machine_type = excluded.machine_type,
  machine_match = excluded.machine_match,
  machines_all = excluded.machines_all,
  qty_produced = excluded.qty_produced,
  run_date = excluded.run_date,
  run_date_raw = excluded.run_date_raw,
  lot_number = excluded.lot_number,
  lot_date = excluded.lot_date,
  operator_initials = excluded.operator_initials,
  material_raw = excluded.material_raw,
  drawing_rev = excluded.drawing_rev,
  tso_rev = excluded.tso_rev,
  start_date = excluded.start_date,
  due_date = excluded.due_date,
  final_process = excluded.final_process,
  manufacturing_no = excluded.manufacturing_no,
  heat_lot = excluded.heat_lot,
  traveler_notes = excluded.traveler_notes,
  ops = excluded.ops,
  flags = excluded.flags,
  review_status = case when historical_runs.review_note is not null then historical_runs.review_status else excluded.review_status end,
  loaded_at = now();

/* VERIFY (expect: rows = 548, fingerprint = 8185b2a0542c9caa8beecc97b96bd6f5) */
select count(*) as rows,
       md5(string_agg(md5(source_file || '|' || coalesce(qty_produced::text, '') || '|' || coalesce(run_date::text, '') || '|' || coalesce(machine_on_traveler, '')),
                      '' order by md5(source_file || '|' || coalesce(qty_produced::text, '') || '|' || coalesce(run_date::text, '') || '|' || coalesce(machine_on_traveler, '')) collate "C")) as fingerprint
  from public.historical_runs
 where extract_batch = 'traveler_extract 2026-10-28' and folder_year = 2022;
